import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import { API, graphqlOperation } from "aws-amplify";
import { export_participant_workflows } from "@/graphql/mutations";
import axios from "axios";
import FileSaver from "file-saver";
import { get_workflows } from "@/mixins/GetWorkflowsummary.js";
export default {
  name: "ExportParticipatedDialog",
  mixins: [get_workflows],
  props: {
    ExportDialog: Boolean
  },
  emits: ["close", "successMsg", "errorMsg"],
  data() {
    return {
      loading: false,
      selectedStatus: "ALL",
      selectedWorkflow: "ALL",
      // API values
      internalFields: [],
      // UI chips
      displayFields: [],
      isAllSelected: false,
      workflowItems: [],
      statusItems: ["ALL", "INPROGRESS", "COMPLETED", "REJECTED", "WITHDRAWN"],
      fields: [{
        title: "ALL",
        value: "__all__"
      }, {
        title: "Transaction ID / Workflow Name",
        value: "transaction_id"
      }, {
        title: "Initiated By",
        value: "workflow_initiated_name"
      }, {
        title: "Summary Field",
        value: "summary_field_1"
      }, {
        title: "Last Acted By",
        value: "workflow_approval_name"
      }, {
        title: "Pending On",
        value: "pending_on"
      }, {
        title: "Initiated On / Acted On",
        value: "workflow_initiated_on"
      }, {
        title: "Status",
        value: "approval_status"
      }]
    };
  },
  async mounted() {
    await this.get_workflows();
    this.workflowItems = this.summaryOrgWorkflows.map(w => w.workflow_name);
  },
  computed: {
    selectedFields: {
      get() {
        return this.displayFields;
      },
      set(val) {
        // ALL selected
        if (val.includes("__all__")) {
          this.isAllSelected = true;

          // API → all fields
          this.internalFields = this.fields.filter(f => f.value !== "__all__").map(f => f.value);

          // UI → only ALL chip
          this.displayFields = ["__all__"];
        }
        // manual selection
        else {
          this.isAllSelected = false;
          this.displayFields = val;
          this.internalFields = val;
        }
      }
    },
    isDisabled() {
      return this.loading || !this.selectedWorkflow || !this.selectedStatus || this.internalFields.length === 0;
    }
  },
  methods: {
    closeDialog() {
      this.resetForm();
      this.$emit("close");
    },
    resetForm() {
      this.selectedStatus = "";
      this.selectedWorkflow = "";
      this.internalFields = [];
      this.displayFields = [];
      this.isAllSelected = false;
    },
    async exportWorkflow() {
      if (this.isDisabled) return;
      try {
        this.loading = true;
        const user = this.$store.getters.GetUserObj;
        const result = await API.graphql(graphqlOperation(export_participant_workflows, {
          input: {
            user_email_id: user.organization.organization_created_by,
            workflow_name: this.selectedWorkflow,
            approval_status: this.selectedStatus,
            export_fields: this.internalFields
          }
        }));
        const response = JSON.parse(result.data.export_participant_workflows);
        if (!response.URL) {
          throw new Error("No data found");
        }
        this.$emit("successMsg", response.message || "Export started");
        await this.downloadFile(response.URL, response.FileName);
      } catch (error) {
        this.$emit("errorMsg", error.message || "Export failed");
      } finally {
        this.loading = false;
      }
    },
    async downloadFile(url, apiFileName) {
      const teamId = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
      const fileName = apiFileName ? `${teamId}_${apiFileName}` : `${teamId}_Export.xlsx`;
      const response = await axios.get(url, {
        responseType: "blob"
      });
      FileSaver.saveAs(new Blob([response.data]), fileName);
    }
  }
};
